class_name World
extends Node3D
## Terrain, airports, city, trees, water, clouds, sky.

const AIRPORT_ALT := 30.0
const STRIP_POS := Vector2(-9000.0, -6500.0)   # mountain airstrip centre (x, z)
const STRIP_ALT := 900.0
const STRIP_HEADING := 60.0                   # degrees, runway direction
const LAKE_POS := Vector2(4200.0, 3200.0)
const SEA_X := 10000.0
const RUNWAY_LEN := 2500.0
const RUNWAY_W := 45.0

var noise := FastNoiseLite.new()
var noise2 := FastNoiseLite.new()
var fast := false
var clouds: Array = []
var sun: DirectionalLight3D
var env: WorldEnvironment
var water: MeshInstance3D
var windsock: Node3D
var trees_mm: MultiMeshInstance3D
var papi: Array = []
var tree_positions: PackedVector3Array = PackedVector3Array()

func _ready() -> void:
	noise.seed = 1337
	noise.noise_type = FastNoiseLite.TYPE_SIMPLEX_SMOOTH
	noise.frequency = 1.0 / 2600.0
	noise.fractal_octaves = 4
	noise2.seed = 42
	noise2.noise_type = FastNoiseLite.TYPE_SIMPLEX_SMOOTH
	noise2.frequency = 1.0 / 9000.0
	noise2.fractal_octaves = 3

func _flat(x: float, z: float, cx: float, cz: float, r0: float, r1: float) -> float:
	var d := Vector2(x - cx, z - cz).length()
	return 1.0 - smoothstep(r0, r1, d)

## Terrain height in metres (water level = 0).
func height(x: float, z: float) -> float:
	var n := noise.get_noise_2d(x, z)
	var h := 30.0 + 160.0 * (n + 0.5)
	var ridge: float = 1.0 - abs(noise2.get_noise_2d(x * 1.5, z * 1.5))
	var mtn := smoothstep(-5000.0, -11000.0, z) * 0.75 + smoothstep(-8500.0, -14000.0, x) * 0.45
	h += mtn * (1800.0 * ridge * ridge + 300.0 * (n + 0.5))
	# east sea with beach
	var sea := smoothstep(SEA_X - 1800.0, SEA_X + 600.0, x)
	h = lerp(h, -30.0, sea)
	# lake
	var lk := _flat(x, z, LAKE_POS.x, LAKE_POS.y, 900.0, 1500.0)
	h = lerp(h, -14.0, lk)
	# airport flat zone
	var ap := _flat(x, z, 0.0, 0.0, 2300.0, 3400.0)
	h = lerp(h, AIRPORT_ALT, ap)
	# mountain strip plateau
	var st := _flat(x, z, STRIP_POS.x, STRIP_POS.y, 800.0, 1500.0)
	h = lerp(h, STRIP_ALT, st)
	return h

## 0 = hard surface (runway/taxiway/apron), 1 = grass/dirt, 2 = water, 3 = rough (mountain, slopes)
func surface(x: float, z: float) -> int:
	if on_runway(x, z) or on_strip(x, z) or on_apron(x, z):
		return 0
	var h := height(x, z)
	if h < 0.3:
		return 2
	var slope: float = abs(height(x + 8.0, z) - height(x - 8.0, z)) + abs(height(x, z + 8.0) - height(x, z - 8.0))
	if slope > 3.0 or h > 1200.0:
		return 3
	return 1

func on_runway(x: float, z: float) -> bool:
	return abs(x) <= RUNWAY_LEN * 0.5 + 60.0 and abs(z) <= RUNWAY_W * 0.5 + 2.0

func on_apron(x: float, z: float) -> bool:
	# taxiway along the south side + apron
	if abs(x) <= RUNWAY_LEN * 0.5 and z > 60.0 and z < 90.0:
		return true
	if x > -400.0 and x < 400.0 and z > 90.0 and z < 330.0:
		return true
	# stub taxiways
	for sx in [-1100.0, 0.0, 1100.0]:
		if abs(x - sx) < 15.0 and z > 0.0 and z < 90.0:
			return true
	return false

func strip_local(x: float, z: float) -> Vector2:
	var d := Vector2(x - STRIP_POS.x, z - STRIP_POS.y)
	var a := deg_to_rad(STRIP_HEADING)
	# local u along runway, v across
	return Vector2(d.x * cos(a) - d.y * sin(a), d.x * sin(a) + d.y * cos(a))

func on_strip(x: float, z: float) -> bool:
	var l := strip_local(x, z)
	return abs(l.x) <= 480.0 and abs(l.y) <= 16.0

func strip_dir() -> Vector3:
	var a := deg_to_rad(STRIP_HEADING)
	return Vector3(cos(a), 0, sin(a))

func build(fast_mode: bool) -> void:
	fast = fast_mode
	_sky()
	_terrain()
	_water()
	_airport()
	_mountain_strip()
	_city()
	_trees()
	_clouds()

func _sky() -> void:
	env = WorldEnvironment.new()
	var e := Environment.new()
	var sky := Sky.new()
	var sm := ProceduralSkyMaterial.new()
	sm.sky_top_color = Color(0.18, 0.42, 0.85)
	sm.sky_horizon_color = Color(0.72, 0.82, 0.95)
	sm.ground_bottom_color = Color(0.3, 0.32, 0.3)
	sm.ground_horizon_color = Color(0.72, 0.8, 0.9)
	sm.sun_angle_max = 25.0
	sm.sun_curve = 0.12
	sky.sky_material = sm
	e.background_mode = Environment.BG_SKY
	e.sky = sky
	e.ambient_light_source = Environment.AMBIENT_SOURCE_SKY
	e.ambient_light_sky_contribution = 1.0
	e.ambient_light_energy = 1.0
	e.tonemap_mode = Environment.TONE_MAPPER_ACES
	e.tonemap_exposure = 1.05
	e.fog_enabled = true
	e.fog_light_color = Color(0.75, 0.83, 0.95)
	e.fog_density = 0.00006 if fast else 0.00005
	e.fog_sky_affect = 0.15
	e.fog_aerial_perspective = 0.6
	e.glow_enabled = not fast
	e.glow_intensity = 0.35
	e.glow_bloom = 0.05
	e.glow_hdr_threshold = 1.1
	env.environment = e
	add_child(env)
	sun = DirectionalLight3D.new()
	sun.rotation_degrees = Vector3(-48, 35, 0)
	sun.light_energy = 1.25
	sun.light_color = Color(1.0, 0.96, 0.9)
	sun.shadow_enabled = not fast
	sun.directional_shadow_mode = DirectionalLight3D.SHADOW_PARALLEL_4_SPLITS
	sun.directional_shadow_max_distance = 420.0
	sun.directional_shadow_split_1 = 0.08
	sun.directional_shadow_split_2 = 0.25
	sun.directional_shadow_split_3 = 0.55
	sun.directional_shadow_blend_splits = true
	sun.shadow_bias = 0.08
	add_child(sun)

func _ground_material() -> StandardMaterial3D:
	var m := StandardMaterial3D.new()
	m.vertex_color_use_as_albedo = true
	var nt := NoiseTexture2D.new()
	var nn := FastNoiseLite.new()
	nn.seed = 9
	nn.frequency = 0.02
	nn.fractal_octaves = 4
	nt.noise = nn
	nt.width = 256
	nt.height = 256
	nt.seamless = true
	nt.as_normal_map = false
	m.albedo_texture = nt
	m.albedo_color = Color(1.35, 1.35, 1.35)
	m.uv1_triplanar = true
	m.uv1_scale = Vector3(0.02, 0.02, 0.02)
	m.roughness = 0.95
	m.texture_filter = BaseMaterial3D.TEXTURE_FILTER_LINEAR_WITH_MIPMAPS_ANISOTROPIC
	return m

func _terrain_color(h: float, slope: float, x: float, z: float) -> Color:
	var c: Color
	var beach := Color(0.78, 0.72, 0.52)
	var grass := Color(0.36, 0.5, 0.2)
	var dry := Color(0.55, 0.55, 0.3)
	var rock := Color(0.42, 0.4, 0.38)
	var snow := Color(0.95, 0.95, 0.97)
	var v := noise.get_noise_2d(x * 3.0 + 500.0, z * 3.0)
	c = grass.lerp(dry, clamp(v * 1.5 + 0.5, 0.0, 1.0) * 0.6)
	c = c.lerp(beach, 1.0 - smoothstep(-2.0, 6.0, h))
	c = c.lerp(rock, smoothstep(0.35, 0.9, slope))
	c = c.lerp(snow, smoothstep(1300.0, 1700.0, h) * (1.0 - smoothstep(0.6, 1.1, slope)))
	return c

func _terrain_mesh(half: float, cells: int, y_off: float, skip_inner: float) -> ArrayMesh:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var step := half * 2.0 / float(cells)
	var hs: PackedFloat32Array = PackedFloat32Array()
	hs.resize((cells + 1) * (cells + 1))
	for j in range(cells + 1):
		for i in range(cells + 1):
			hs[j * (cells + 1) + i] = height(-half + i * step, -half + j * step) + y_off
	var verts: Array = []
	for j in range(cells + 1):
		for i in range(cells + 1):
			var x := -half + i * step
			var z := -half + j * step
			var h := hs[j * (cells + 1) + i]
			var hl := hs[j * (cells + 1) + maxi(i - 1, 0)]
			var hr := hs[j * (cells + 1) + mini(i + 1, cells)]
			var hd := hs[maxi(j - 1, 0) * (cells + 1) + i]
			var hu := hs[mini(j + 1, cells) * (cells + 1) + i]
			var nrm := Vector3(hl - hr, 2.0 * step, hd - hu).normalized()
			var slope := 1.0 - nrm.y
			verts.append([Vector3(x, h, z), nrm, _terrain_color(h - y_off, slope * 4.0, x, z)])
	for j in range(cells):
		for i in range(cells):
			var x := -half + (i + 0.5) * step
			var z := -half + (j + 0.5) * step
			if skip_inner > 0.0 and abs(x) < skip_inner and abs(z) < skip_inner:
				continue
			var a: Array = verts[j * (cells + 1) + i]
			var b: Array = verts[j * (cells + 1) + i + 1]
			var c: Array = verts[(j + 1) * (cells + 1) + i + 1]
			var d: Array = verts[(j + 1) * (cells + 1) + i]
			_tv(st, a); _tv(st, b); _tv(st, c)
			_tv(st, a); _tv(st, c); _tv(st, d)
	return st.commit()

func _tv(st: SurfaceTool, v: Array) -> void:
	st.set_color(v[2])
	st.set_normal(v[1])
	st.add_vertex(v[0])

func _terrain() -> void:
	var m := _ground_material()
	var inner := MeshInstance3D.new()
	inner.mesh = _terrain_mesh(6000.0, 150 if fast else 200, 0.0, 0.0)
	inner.material_override = m
	add_child(inner)
	var outer := MeshInstance3D.new()
	outer.mesh = _terrain_mesh(24000.0, 120 if fast else 160, -3.0, 5800.0)
	outer.material_override = m
	add_child(outer)

func _water() -> void:
	water = MeshInstance3D.new()
	var pm := PlaneMesh.new()
	pm.size = Vector2(48000.0, 48000.0)
	pm.subdivide_depth = 20
	pm.subdivide_width = 20
	water.mesh = pm
	var wm := ShaderMaterial.new()
	wm.shader = load("res://shaders/water.gdshader")
	water.material_override = wm
	water.position = Vector3(0, 0.0, 0)
	add_child(water)

func _asphalt() -> StandardMaterial3D:
	return Geo.mat(Color(0.2, 0.2, 0.21), 0.95)

func _airport() -> void:
	var y := AIRPORT_ALT
	var asph := _asphalt()
	var white := Geo.mat(Color(0.95, 0.95, 0.9), 0.6)
	var yellow := Geo.mat(Color(0.95, 0.8, 0.2), 0.6)
	# runway 09/27 along X
	Geo.box(self, Vector3(RUNWAY_LEN + 120.0, 0.3, RUNWAY_W), asph, Vector3(0, y + 0.1, 0))
	# centreline dashes
	var x := -RUNWAY_LEN * 0.5 + 100.0
	while x < RUNWAY_LEN * 0.5 - 100.0:
		Geo.box(self, Vector3(30.0, 0.05, 0.9), white, Vector3(x + 15.0, y + 0.28, 0))
		x += 60.0
	# threshold bars + numbers
	for sx in [-1.0, 1.0]:
		var tx: float = sx * (RUNWAY_LEN * 0.5 - 20.0)
		for k in range(8):
			var zz := -RUNWAY_W * 0.5 + 4.0 + float(k) * 5.2
			Geo.box(self, Vector3(30.0, 0.05, 1.8), white, Vector3(tx, y + 0.28, zz))
		# aiming point bars
		Geo.box(self, Vector3(45.0, 0.05, 4.0), white, Vector3(sx * (RUNWAY_LEN * 0.5 - 320.0), y + 0.28, -9.0))
		Geo.box(self, Vector3(45.0, 0.05, 4.0), white, Vector3(sx * (RUNWAY_LEN * 0.5 - 320.0), y + 0.28, 9.0))
		# touchdown zone stripes
		for k in range(3):
			for zz in [-14.0, -10.0, 10.0, 14.0]:
				Geo.box(self, Vector3(20.0, 0.05, 1.6), white, Vector3(sx * (RUNWAY_LEN * 0.5 - 170.0 - float(k) * 150.0), y + 0.28, zz))
		_runway_number(Vector3(sx * (RUNWAY_LEN * 0.5 - 85.0), y + 0.29, 0), "09" if sx < 0 else "27", sx < 0)
		# edge lights
	var xl := -RUNWAY_LEN * 0.5
	while xl <= RUNWAY_LEN * 0.5:
		for zz in [-RUNWAY_W * 0.5 - 1.0, RUNWAY_W * 0.5 + 1.0]:
			Geo.box(self, Vector3(0.4, 0.4, 0.4), Geo.mat(Color(1, 1, 1), 0.3, 0.0, Color(1, 1, 0.8)), Vector3(xl, y + 0.4, zz))
		xl += 100.0
	# taxiway + apron
	Geo.box(self, Vector3(RUNWAY_LEN, 0.25, 30.0), asph, Vector3(0, y + 0.08, 75.0))
	Geo.box(self, Vector3(800.0, 0.25, 240.0), asph, Vector3(0, y + 0.08, 210.0))
	for sx in [-1100.0, 0.0, 1100.0]:
		Geo.box(self, Vector3(30.0, 0.25, 70.0), asph, Vector3(sx, y + 0.08, 40.0))
	# taxiway centreline (yellow)
	Geo.box(self, Vector3(RUNWAY_LEN - 40.0, 0.04, 0.6), yellow, Vector3(0, y + 0.22, 75.0))
	# parking spots
	for k in range(6):
		Geo.box(self, Vector3(0.6, 0.04, 40.0), yellow, Vector3(-300.0 + float(k) * 120.0, y + 0.22, 190.0))
	# terminal, hangars, tower
	var wall := Geo.mat(Color(0.82, 0.8, 0.75), 0.8)
	var roof := Geo.mat(Color(0.5, 0.52, 0.55), 0.7)
	Geo.box(self, Vector3(260.0, 14.0, 40.0), wall, Vector3(0, y + 7.0, 360.0))
	Geo.box(self, Vector3(266.0, 2.0, 46.0), roof, Vector3(0, y + 15.0, 360.0))
	Geo.box(self, Vector3(250.0, 6.0, 1.0), Geo.glass(Color(0.3, 0.5, 0.7, 0.6)), Vector3(0, y + 7.0, 339.5))
	for k in range(3):
		var hx := -420.0 + float(k) * 70.0
		Geo.box(self, Vector3(60.0, 18.0, 70.0), Geo.mat(Color(0.9, 0.35, 0.25), 0.7), Vector3(hx, y + 9.0, 400.0))
		var hr := Geo.box(self, Vector3(60.0, 1.0, 72.0), roof, Vector3(hx, y + 19.0, 400.0))
		hr.rotation_degrees = Vector3.ZERO
		Geo.box(self, Vector3(40.0, 14.0, 1.0), Geo.mat(Color(0.3, 0.3, 0.32)), Vector3(hx, y + 7.0, 364.0))
	# control tower
	Geo.cyl(self, 4.0, 40.0, wall, Vector3(380.0, y + 20.0, 360.0))
	Geo.cyl(self, 9.0, 8.0, Geo.glass(Color(0.2, 0.4, 0.6, 0.6)), Vector3(380.0, y + 44.0, 360.0))
	Geo.cyl(self, 10.0, 1.5, roof, Vector3(380.0, y + 48.5, 360.0))
	# PAPI lights (4 boxes, left side of runway 09 threshold)
	for k in range(4):
		var p := Geo.box(self, Vector3(1.2, 1.0, 1.0), Geo.mat(Color(1, 1, 1), 0.3, 0.0, Color(1, 1, 1)), Vector3(-RUNWAY_LEN * 0.5 + 300.0, y + 0.8, -RUNWAY_W * 0.5 - 12.0 - float(k) * 3.0))
		papi.append(p)
	# windsock
	windsock = Node3D.new()
	windsock.position = Vector3(-600.0, y, -60.0)
	add_child(windsock)
	Geo.cyl(windsock, 0.15, 8.0, Geo.mat(Color(0.9, 0.9, 0.9)), Vector3(0, 4.0, 0))
	var sock := Geo.cyl(windsock, 0.25, 3.2, Geo.mat(Color(0.95, 0.4, 0.1)), Vector3(1.6, 8.0, 0), Vector3(0, 0, 90), 0.6, "Sock")
	sock.name = "Sock"
	# parked planes (static props)
	for k in range(3):
		var pp := Planes.build(["trainer", "aerobat", "trainer"][k], [Color(0.9, 0.2, 0.2), Color(0.2, 0.4, 0.9), Color(0.95, 0.75, 0.1)][k])
		pp.position = Vector3(-300.0 + float(k) * 120.0, y + 1.35, 200.0)
		pp.rotation_degrees = Vector3(0, 180, 0)
		add_child(pp)
	# fuel trucks / cars
	for k in range(4):
		Geo.box(self, Vector3(2.4, 2.4, 7.0), Geo.mat([Color(0.9, 0.9, 0.2), Color(0.2, 0.6, 0.3), Color(0.8, 0.8, 0.8), Color(0.2, 0.3, 0.8)][k]), Vector3(180.0 + float(k) * 14.0, y + 1.3, 300.0))
	# beacon
	Geo.sphere(self, 1.2, Geo.mat(Color(1, 1, 1), 0.3, 0.0, Color(1, 1, 1)), Vector3(380.0, y + 51.0, 360.0))

func _runway_number(pos: Vector3, txt: String, flip: bool) -> void:
	# 7-segment style digits made of boxes, laid flat, 12 m tall, read by a pilot on approach
	var white := Geo.mat(Color(0.95, 0.95, 0.9), 0.6)
	var segs := {
		"0": [1, 1, 1, 1, 1, 1, 0], "2": [1, 1, 0, 1, 1, 0, 1], "7": [1, 1, 1, 0, 0, 0, 0], "9": [1, 1, 1, 1, 0, 1, 1],
	}
	var n := Node3D.new()
	n.position = pos
	n.rotation_degrees = Vector3(0, -90.0 if flip else 90.0, 0)
	add_child(n)
	var i := 0
	for ch in txt:
		var s: Array = segs.get(ch, segs["0"])
		var ox := -4.5 + float(i) * 9.0
		var H := 6.0
		var W := 3.5
		# a top, b top-right, c bottom-right, d bottom, e bottom-left, f top-left, g middle; drawn in local x (across) and z (along)
		var items := [
			[Vector3(ox, 0, -H), Vector3(W * 2.0, 0.05, 1.2)],
			[Vector3(ox + W, 0, -H * 0.5), Vector3(1.2, 0.05, H)],
			[Vector3(ox + W, 0, H * 0.5), Vector3(1.2, 0.05, H)],
			[Vector3(ox, 0, H), Vector3(W * 2.0, 0.05, 1.2)],
			[Vector3(ox - W, 0, H * 0.5), Vector3(1.2, 0.05, H)],
			[Vector3(ox - W, 0, -H * 0.5), Vector3(1.2, 0.05, H)],
			[Vector3(ox, 0, 0), Vector3(W * 2.0, 0.05, 1.2)],
		]
		for k in range(7):
			if s[k] == 1:
				Geo.box(n, items[k][1], white, items[k][0])
		i += 1

func _mountain_strip() -> void:
	var y := STRIP_ALT
	var n := Node3D.new()
	n.position = Vector3(STRIP_POS.x, y, STRIP_POS.y)
	n.rotation_degrees = Vector3(0, -STRIP_HEADING, 0)
	add_child(n)
	Geo.box(n, Vector3(960.0, 0.3, 32.0), Geo.mat(Color(0.55, 0.5, 0.42), 0.95), Vector3(0, 0.1, 0))
	var x := -440.0
	while x < 440.0:
		Geo.box(n, Vector3(20.0, 0.05, 0.8), Geo.mat(Color(0.95, 0.95, 0.9)), Vector3(x, 0.28, 0))
		x += 50.0
	for sx in [-1.0, 1.0]:
		for k in range(5):
			Geo.box(n, Vector3(20.0, 0.05, 1.6), Geo.mat(Color(0.95, 0.95, 0.9)), Vector3(sx * 455.0, 0.28, -12.0 + float(k) * 6.0))
	# small hangar + windsock + cabins
	Geo.box(n, Vector3(30.0, 10.0, 25.0), Geo.mat(Color(0.5, 0.3, 0.2)), Vector3(100.0, 5.0, 45.0))
	Geo.box(n, Vector3(32.0, 1.0, 27.0), Geo.mat(Color(0.3, 0.3, 0.32)), Vector3(100.0, 10.5, 45.0))
	Geo.cyl(n, 0.15, 7.0, Geo.mat(Color(0.9, 0.9, 0.9)), Vector3(-200.0, 3.5, -40.0))
	Geo.cyl(n, 0.25, 3.0, Geo.mat(Color(0.95, 0.4, 0.1)), Vector3(-198.5, 7.0, -40.0), Vector3(0, 0, 90), 0.6)
	for k in range(3):
		Geo.box(n, Vector3(8.0, 4.0, 8.0), Geo.mat(Color(0.55, 0.35, 0.2)), Vector3(-100.0 + float(k) * 20.0, 2.0, 60.0))
		var r := Geo.box(n, Vector3(9.0, 3.0, 9.0), Geo.mat(Color(0.35, 0.2, 0.15)), Vector3(-100.0 + float(k) * 20.0, 5.0, 60.0))
		r.rotation_degrees = Vector3(0, 0, 0)

func _city() -> void:
	var rng := RandomNumberGenerator.new()
	rng.seed = 5
	var cols := [Color(0.75, 0.75, 0.78), Color(0.6, 0.65, 0.7), Color(0.8, 0.7, 0.6), Color(0.5, 0.55, 0.65), Color(0.85, 0.85, 0.82)]
	var glass := Geo.glass(Color(0.3, 0.5, 0.7, 0.75))
	# city on the flat zone north-west of the airport
	var cx := -2600.0
	var cz := -1500.0
	var mm := MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.use_colors = true
	var count := 0
	var items: Array = []
	for i in range(14):
		for j in range(12):
			if rng.randf() < 0.12:
				continue
			var x := cx + float(i) * 95.0 + rng.randf_range(-10, 10)
			var z := cz + float(j) * 95.0 + rng.randf_range(-10, 10)
			var d := Vector2(x - cx - 650.0, z - cz - 550.0).length()
			var hgt: float = rng.randf_range(12.0, 40.0) + max(0.0, 140.0 - d * 0.22) * rng.randf_range(0.5, 1.5)
			var w := rng.randf_range(30.0, 60.0)
			var dpt := rng.randf_range(30.0, 60.0)
			var y := height(x, z)
			items.append([Vector3(x, y + hgt * 0.5, z), Vector3(w, hgt, dpt), cols[rng.randi() % cols.size()]])
			count += 1
	var bm := BoxMesh.new()
	bm.size = Vector3.ONE
	mm.mesh = bm
	mm.instance_count = count
	for k in range(count):
		var it: Array = items[k]
		var t := Transform3D(Basis.from_scale(it[1]), it[0])
		mm.set_instance_transform(k, t)
		mm.set_instance_color(k, it[2])
	var mmi := MultiMeshInstance3D.new()
	mmi.multimesh = mm
	var m := StandardMaterial3D.new()
	m.vertex_color_use_as_albedo = true
	m.roughness = 0.6
	mmi.material_override = m
	add_child(mmi)
	# a few glass towers
	for k in range(3):
		var it: Array = items[k * 7 + 3]
		Geo.box(self, Vector3(it[1].x * 0.8, it[1].y * 1.4, it[1].z * 0.8), glass, Vector3(it[0].x, it[0].y * 1.0 + it[1].y * 0.2, it[0].z))
	# roads grid (dark strips on the ground)
	var road := Geo.mat(Color(0.18, 0.18, 0.19), 0.95)
	for i in range(15):
		Geo.box(self, Vector3(14.0, 0.3, 1200.0), road, Vector3(cx - 47.0 + float(i) * 95.0, height(cx, cz) + 0.2, cz + 520.0))
	for j in range(13):
		Geo.box(self, Vector3(1400.0, 0.3, 14.0), road, Vector3(cx + 620.0, height(cx, cz) + 0.2, cz - 47.0 + float(j) * 95.0))
	# wind turbines on the hills east
	for k in range(6):
		var tx := 5500.0 + float(k) * 420.0
		var tz := -2500.0 + float(k % 2) * 600.0
		var ty := height(tx, tz)
		Geo.cyl(self, 1.6, 80.0, Geo.mat(Color(0.92, 0.92, 0.95)), Vector3(tx, ty + 40.0, tz), Vector3.ZERO, 2.6)
		var hub := Node3D.new()
		hub.position = Vector3(tx, ty + 80.0, tz - 3.0)
		hub.name = "Turbine%d" % k
		add_child(hub)
		for b in range(3):
			var bl := Geo.box(hub, Vector3(2.2, 40.0, 0.5), Geo.mat(Color(0.92, 0.92, 0.95)), Vector3(0, 0, 0))
			bl.rotation_degrees = Vector3(0, 0, float(b) * 120.0)
			bl.position = Vector3(sin(deg_to_rad(float(b) * 120.0)) * -20.0, cos(deg_to_rad(float(b) * 120.0)) * 20.0, 0)
		clouds.append(hub)  # reuse rotation list via main (turbines spin)

func _trees() -> void:
	var rng := RandomNumberGenerator.new()
	rng.seed = 11
	var n := 2200 if fast else 4500
	var mm := MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.use_colors = true
	# tree = trunk + cone canopy merged
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var tri := 8
	for layer in range(3):
		var y0 := 6.0 + float(layer) * 5.0
		var r := 7.0 - float(layer) * 1.8
		var top := Vector3(0, y0 + 7.0, 0)
		for i in range(tri):
			var a0 := TAU * float(i) / float(tri)
			var a1 := TAU * float(i + 1) / float(tri)
			var p0 := Vector3(cos(a0) * r, y0, sin(a0) * r)
			var p1 := Vector3(cos(a1) * r, y0, sin(a1) * r)
			st.set_color(Color(0.25, 0.45, 0.18))
			st.add_vertex(top); st.add_vertex(p1); st.add_vertex(p0)
	for i in range(6):
		var a0 := TAU * float(i) / 6.0
		var a1 := TAU * float(i + 1) / 6.0
		var p0 := Vector3(cos(a0) * 0.8, 0, sin(a0) * 0.8)
		var p1 := Vector3(cos(a1) * 0.8, 0, sin(a1) * 0.8)
		st.set_color(Color(0.35, 0.22, 0.12))
		st.add_vertex(p0); st.add_vertex(p1); st.add_vertex(p1 + Vector3(0, 7, 0))
		st.add_vertex(p0); st.add_vertex(p1 + Vector3(0, 7, 0)); st.add_vertex(p0 + Vector3(0, 7, 0))
	st.generate_normals()
	mm.mesh = st.commit()
	var placed := 0
	mm.instance_count = n
	var tries := 0
	while placed < n and tries < n * 20:
		tries += 1
		var x := rng.randf_range(-11000.0, 9000.0)
		var z := rng.randf_range(-9000.0, 11000.0)
		var h := height(x, z)
		if h < 8.0 or h > 1150.0:
			continue
		if abs(x) < 1500.0 and abs(z) < 700.0:
			continue
		if x > -3000.0 and x < -1000.0 and z > -1700.0 and z < -200.0:
			continue
		if on_strip(x, z):
			continue
		var slope: float = abs(height(x + 10.0, z) - h) + abs(height(x, z + 10.0) - h)
		if slope > 5.0:
			continue
		var forest := noise.get_noise_2d(x * 2.0 + 9000.0, z * 2.0)
		if forest < 0.05 and rng.randf() > 0.25:
			continue
		var s := rng.randf_range(0.9, 1.7)
		var t := Transform3D(Basis.from_euler(Vector3(0, rng.randf() * TAU, 0)).scaled(Vector3(s, s, s)), Vector3(x, h - 0.5, z))
		mm.set_instance_transform(placed, t)
		mm.set_instance_color(placed, Color(rng.randf_range(0.7, 1.1), rng.randf_range(0.8, 1.1), rng.randf_range(0.7, 1.0)))
		tree_positions.append(Vector3(x, h, z))
		placed += 1
	mm.visible_instance_count = placed
	trees_mm = MultiMeshInstance3D.new()
	trees_mm.multimesh = mm
	var m := StandardMaterial3D.new()
	m.vertex_color_use_as_albedo = true
	m.roughness = 0.9
	trees_mm.material_override = m
	trees_mm.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON
	add_child(trees_mm)

var cloud_nodes: Array = []

func _clouds() -> void:
	var rng := RandomNumberGenerator.new()
	rng.seed = 3
	var m := StandardMaterial3D.new()
	m.albedo_color = Color(1, 1, 1, 0.85)
	m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	m.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	m.billboard_mode = BaseMaterial3D.BILLBOARD_ENABLED
	var tex := GradientTexture2D.new()
	var g := Gradient.new()
	g.set_color(0, Color(1, 1, 1, 1))
	g.set_color(1, Color(1, 1, 1, 0))
	g.add_point(0.55, Color(1, 1, 1, 0.9))
	tex.gradient = g
	tex.fill = GradientTexture2D.FILL_RADIAL
	tex.fill_from = Vector2(0.5, 0.5)
	tex.fill_to = Vector2(0.5, 0.0)
	tex.width = 128
	tex.height = 128
	m.albedo_texture = tex
	var count := 50 if fast else 90
	for i in range(count):
		var cx := rng.randf_range(-12000.0, 12000.0)
		var cz := rng.randf_range(-12000.0, 12000.0)
		var cy := rng.randf_range(1400.0, 2600.0)
		var cl := Node3D.new()
		cl.position = Vector3(cx, cy, cz)
		add_child(cl)
		var puffs := rng.randi_range(4, 8)
		for p in range(puffs):
			var q := QuadMesh.new()
			var sz := rng.randf_range(280.0, 520.0)
			q.size = Vector2(sz, sz * 0.6)
			var mi := MeshInstance3D.new()
			mi.mesh = q
			mi.material_override = m
			mi.position = Vector3(rng.randf_range(-350.0, 350.0), rng.randf_range(-40.0, 80.0), rng.randf_range(-350.0, 350.0))
			cl.add_child(mi)
		cloud_nodes.append(cl)

func tick(dt: float, t: float, wind: Vector3) -> void:
	for c in cloud_nodes:
		c.position += wind * dt * 2.0
		if c.position.x > 13000.0:
			c.position.x -= 26000.0
		if c.position.z > 13000.0:
			c.position.z -= 26000.0
	for h in clouds:
		h.rotation.z += dt * 0.6
	if windsock:
		var ws: Node3D = windsock.get_node_or_null("Sock")
		var wl := Vector2(wind.x, wind.z).length()
		windsock.rotation.y = -atan2(wind.z, wind.x)
		if ws:
			ws.rotation_degrees.z = 10.0 + clamp(wl * 8.0, 0.0, 80.0)
	if water:
		var wm: ShaderMaterial = water.material_override
		wm.set_shader_parameter("t", t)

## PAPI: 2 white 2 red on a 3 degree glide path for runway 09 (approach from the west)
func update_papi(pos: Vector3) -> void:
	var px := -RUNWAY_LEN * 0.5 + 300.0
	var dx := px - pos.x
	if dx <= 50.0:
		return
	var ang := rad_to_deg(atan2(pos.y - AIRPORT_ALT, dx))
	var reds := 2
	if ang > 3.5:
		reds = 0
	elif ang > 3.17:
		reds = 1
	elif ang > 2.83:
		reds = 2
	elif ang > 2.5:
		reds = 3
	else:
		reds = 4
	for k in range(4):
		var mi: MeshInstance3D = papi[k]
		var m: StandardMaterial3D = mi.material_override
		var red := k < reds
		m.albedo_color = Color(1, 0.15, 0.1) if red else Color(1, 1, 1)
		m.emission = Color(1, 0.1, 0.05) if red else Color(1, 1, 1)

