class_name Geo
## Procedural mesh helpers (SurfaceTool based). Forward is -Z, right +X, up +Y.

static func mat(col: Color, rough: float = 0.6, metal: float = 0.0, emis: Color = Color(0, 0, 0)) -> StandardMaterial3D:
	var m := StandardMaterial3D.new()
	m.albedo_color = col
	m.roughness = rough
	m.metallic = metal
	if emis.r + emis.g + emis.b > 0.0:
		m.emission_enabled = true
		m.emission = emis
		m.emission_energy_multiplier = 1.5
	return m

static func glass(col: Color = Color(0.3, 0.5, 0.7, 0.55)) -> StandardMaterial3D:
	var m := StandardMaterial3D.new()
	m.albedo_color = col
	m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	m.roughness = 0.05
	m.metallic = 0.3
	m.cull_mode = BaseMaterial3D.CULL_DISABLED
	return m

## Build a smooth "lofted" tube. sections: Array of Dictionary {z, y, w, h, r}
## z = position along length, y = centre height, w = width, h = height, r = roundness 0..1 (0 = box, 1 = ellipse)
static func loft(sections: Array, segs: int = 16, close_front: bool = true, close_back: bool = true) -> ArrayMesh:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var rings: Array = []
	for s in sections:
		var ring: PackedVector3Array = PackedVector3Array()
		var w: float = s.get("w", 1.0) * 0.5
		var h: float = s.get("h", 1.0) * 0.5
		var r: float = s.get("r", 1.0)
		var cy: float = s.get("y", 0.0)
		var cx: float = s.get("x", 0.0)
		for i in range(segs):
			var a := TAU * float(i) / float(segs)
			var cx0 := cos(a)
			var sy0 := sin(a)
			# superellipse-ish blend between circle and square
			var p := 2.0 + (1.0 - r) * 6.0
			var ex: float = pow(abs(cx0), 2.0 / p) * sign(cx0)
			var ey: float = pow(abs(sy0), 2.0 / p) * sign(sy0)
			ring.append(Vector3(cx + ex * w, cy + ey * h, s.get("z", 0.0)))
		rings.append(ring)
	for k in range(rings.size() - 1):
		var a: PackedVector3Array = rings[k]
		var b: PackedVector3Array = rings[k + 1]
		for i in range(segs):
			var j := (i + 1) % segs
			_quad(st, a[i], b[i], b[j], a[j])
	if close_front:
		var r0: PackedVector3Array = rings[0]
		var c := Vector3.ZERO
		for v in r0:
			c += v
		c /= float(segs)
		for i in range(segs):
			var j := (i + 1) % segs
			_tri(st, c, r0[i], r0[j])
	if close_back:
		var r1: PackedVector3Array = rings[rings.size() - 1]
		var c2 := Vector3.ZERO
		for v in r1:
			c2 += v
		c2 /= float(segs)
		for i in range(segs):
			var j := (i + 1) % segs
			_tri(st, c2, r1[j], r1[i])
	st.generate_normals()
	return st.commit()

## Wing: root at local origin, extends in +X (span), chord along Z (leading edge at -Z side).
## sweep = leading edge sweep (deg, positive = back), dihedral in deg, thick = thickness ratio.
static func wing(root_chord: float, tip_chord: float, span: float, sweep_deg: float, dihedral_deg: float, thick: float, mirror: bool = false, camber: float = 0.03) -> ArrayMesh:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var n := 10
	var prof: Array = []
	# airfoil profile: upper and lower as fraction of chord (x from 0 LE to 1 TE)
	for i in range(n + 1):
		var x := float(i) / float(n)
		var t := thick * 5.0 * (0.2969 * sqrt(x) - 0.126 * x - 0.3516 * x * x + 0.2843 * x * x * x - 0.1015 * x * x * x * x)
		var c := camber * 4.0 * x * (1.0 - x)
		prof.append([x, c + t, c - t])
	var sw := tan(deg_to_rad(sweep_deg))
	var dh := tan(deg_to_rad(dihedral_deg))
	var sgn := -1.0 if mirror else 1.0
	var secs: Array = []
	var ns := 6
	for k in range(ns + 1):
		var f := float(k) / float(ns)
		var chord: float = lerp(root_chord, tip_chord, f)
		var xo := span * f
		var le := -chord * 0.0 + sw * xo  # leading edge z (forward = -z; sweep moves LE back = +z)
		var up: PackedVector3Array = PackedVector3Array()
		var lo: PackedVector3Array = PackedVector3Array()
		for p in prof:
			var z: float = le - chord * 0.3 + p[0] * chord
			up.append(Vector3(sgn * xo, dh * xo + p[1] * chord, z))
			lo.append(Vector3(sgn * xo, dh * xo + p[2] * chord, z))
		secs.append([up, lo])
	for k in range(ns):
		var a: Array = secs[k]
		var b: Array = secs[k + 1]
		for i in range(n):
			if mirror:
				_quad(st, a[0][i], a[0][i + 1], b[0][i + 1], b[0][i])
				_quad(st, a[1][i + 1], a[1][i], b[1][i], b[1][i + 1])
			else:
				_quad(st, a[0][i], b[0][i], b[0][i + 1], a[0][i + 1])
				_quad(st, a[1][i + 1], b[1][i + 1], b[1][i], a[1][i])
		# trailing edge closure
		if mirror:
			_quad(st, a[0][n], a[1][n], b[1][n], b[0][n])
		else:
			_quad(st, a[0][n], b[0][n], b[1][n], a[1][n])
	# tip cap
	var tip: Array = secs[ns]
	for i in range(n):
		if mirror:
			_quad(st, tip[0][i], tip[1][i], tip[1][i + 1], tip[0][i + 1])
		else:
			_quad(st, tip[0][i], tip[0][i + 1], tip[1][i + 1], tip[1][i])
	var rt: Array = secs[0]
	for i in range(n):
		if mirror:
			_quad(st, rt[0][i], rt[0][i + 1], rt[1][i + 1], rt[1][i])
		else:
			_quad(st, rt[0][i], rt[1][i], rt[1][i + 1], rt[0][i + 1])
	st.generate_normals()
	return st.commit()

static func _quad(st: SurfaceTool, a: Vector3, b: Vector3, c: Vector3, d: Vector3) -> void:
	st.add_vertex(a); st.add_vertex(b); st.add_vertex(c)
	st.add_vertex(a); st.add_vertex(c); st.add_vertex(d)

static func _tri(st: SurfaceTool, a: Vector3, b: Vector3, c: Vector3) -> void:
	st.add_vertex(a); st.add_vertex(b); st.add_vertex(c)

static func inst(parent: Node3D, mesh: Mesh, m: Material, pos: Vector3 = Vector3.ZERO, rot: Vector3 = Vector3.ZERO, scl: Vector3 = Vector3.ONE, nm: String = "") -> MeshInstance3D:
	var mi := MeshInstance3D.new()
	mi.mesh = mesh
	mi.material_override = m
	mi.position = pos
	mi.rotation_degrees = rot
	mi.scale = scl
	if nm != "":
		mi.name = nm
	parent.add_child(mi)
	return mi

static func box(parent: Node3D, size: Vector3, m: Material, pos: Vector3, rot: Vector3 = Vector3.ZERO, nm: String = "") -> MeshInstance3D:
	var b := BoxMesh.new()
	b.size = size
	return inst(parent, b, m, pos, rot, Vector3.ONE, nm)

static func cyl(parent: Node3D, r: float, h: float, m: Material, pos: Vector3, rot: Vector3 = Vector3.ZERO, r2: float = -1.0, nm: String = "") -> MeshInstance3D:
	var c := CylinderMesh.new()
	c.top_radius = r
	c.bottom_radius = r if r2 < 0.0 else r2
	c.height = h
	c.radial_segments = 20
	return inst(parent, c, m, pos, rot, Vector3.ONE, nm)

static func sphere(parent: Node3D, r: float, m: Material, pos: Vector3, scl: Vector3 = Vector3.ONE, nm: String = "") -> MeshInstance3D:
	var s := SphereMesh.new()
	s.radius = r
	s.height = r * 2.0
	s.radial_segments = 20
	s.rings = 12
	return inst(parent, s, m, pos, Vector3.ZERO, scl, nm)

## Wheel with tyre + hub
static func wheel(parent: Node3D, r: float, w: float, pos: Vector3, nm: String = "") -> Node3D:
	var n := Node3D.new()
	n.position = pos
	if nm != "":
		n.name = nm
	parent.add_child(n)
	cyl(n, r, w, mat(Color(0.08, 0.08, 0.09), 0.9), Vector3.ZERO, Vector3(0, 0, 90))
	cyl(n, r * 0.55, w * 1.05, mat(Color(0.75, 0.75, 0.78), 0.4, 0.8), Vector3.ZERO, Vector3(0, 0, 90))
	return n

