class_name Hud
extends Control
## Cockpit instruments drawn with _draw(): airspeed, attitude, altimeter, VSI, heading, engine, flaps/gear/trim.

var plane: Aircraft
var font: Font
var font_b: Font
var font_t: Font
var nav_text := ""
var nav_bearing := -1.0
var nav_dist := 0.0
var warn_text := ""
var checklist: Array = []     # [text, done]
var mission_line := ""
var time_line := ""
var show_instruments := true
var compact := false
var t := 0.0

func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)

func _process(dt: float) -> void:
	t += dt
	queue_redraw()

func _draw() -> void:
	if plane == null or plane.spec.is_empty():
		return
	var sz := get_viewport_rect().size
	compact = sz.x < 900.0
	var gauge_r := 54.0 if not compact else 40.0
	var gap := 12.0
	var n := 6
	var total := n * (gauge_r * 2.0 + gap) - gap
	var x0 := sz.x * 0.5 - total * 0.5 + gauge_r
	var y := sz.y - gauge_r - 14.0
	# panel background
	var panel := Rect2(x0 - gauge_r - 10.0, y - gauge_r - 30.0, total + 20.0, gauge_r * 2.0 + 44.0)
	draw_rect(panel, Color(0.06, 0.07, 0.09, 0.78))
	draw_rect(panel, Color(0.35, 0.4, 0.5, 0.5), false, 2.0)
	var p := plane
	var kt := p.airspeed / Planes.KT
	_asi(Vector2(x0, y), gauge_r, kt)
	_attitude(Vector2(x0 + (gauge_r * 2.0 + gap), y), gauge_r, p.pitch_deg(), p.bank_deg())
	_altimeter(Vector2(x0 + 2.0 * (gauge_r * 2.0 + gap), y), gauge_r, p.altitude_ft())
	_vsi(Vector2(x0 + 3.0 * (gauge_r * 2.0 + gap), y), gauge_r, p.vs / Planes.FT * 60.0)
	_heading(Vector2(x0 + 4.0 * (gauge_r * 2.0 + gap), y), gauge_r, p.heading_deg())
	_engine(Vector2(x0 + 5.0 * (gauge_r * 2.0 + gap), y), gauge_r)
	# status strip above gauges
	var sy := y - gauge_r - 18.0
	var fs := 13 if compact else 15
	var items: Array = []
	items.append("FLAPS %s" % p.spec.flap_names[p.flap_idx] if p.spec.flaps.size() > 1 else "NO FLAPS")
	if p.spec.retract:
		items.append("GEAR %s" % ("DOWN" if p.gear_pos > 0.95 else ("UP" if p.gear_pos < 0.05 else "...")))
	items.append("TRIM %+d" % int(round(p.trim * 10.0)))
	if p.park:
		items.append("PARK BRAKE")
	elif p.brake > 0.5:
		items.append("BRAKES")
	if p.airbrake:
		items.append("AIRBRAKE" if p.spec.id == "viper" else "SPOILERS")
	if p.reverse:
		items.append("REVERSE")
	if p.ab:
		items.append("AB")
	items.append("G %.1f" % p.gforce)
	items.append("FUEL %d%%" % int(p.fuel * 100.0))
	var txt := "   ".join(items)
	draw_string(font_b, Vector2(panel.position.x + 10.0, sy + 4.0), txt, HORIZONTAL_ALIGNMENT_LEFT, panel.size.x - 20.0, fs, Color(0.8, 0.9, 1.0))
	# warnings
	if warn_text != "" and fmod(t, 0.6) < 0.4:
		var ws := 30 if not compact else 22
		var w := font_t.get_string_size(warn_text, HORIZONTAL_ALIGNMENT_CENTER, -1, ws).x + 30.0
		var wr := Rect2(sz.x * 0.5 - w * 0.5, sz.y * 0.5 - 90.0, w, ws + 14.0)
		draw_rect(wr, Color(0.6, 0.05, 0.05, 0.8))
		draw_string(font_t, Vector2(wr.position.x + 15.0, wr.position.y + ws + 2.0), warn_text, HORIZONTAL_ALIGNMENT_LEFT, -1, ws, Color(1, 1, 1))
	# nav / mission info top
	var top_y := 34.0
	if mission_line != "":
		draw_string(font_t, Vector2(sz.x * 0.5, top_y), mission_line, HORIZONTAL_ALIGNMENT_CENTER, -1, 20 if not compact else 15, Color(1, 1, 1))
		var w2 := font_t.get_string_size(mission_line, HORIZONTAL_ALIGNMENT_CENTER, -1, 20 if not compact else 15).x
		# (shadow)
	if time_line != "":
		draw_string(font_t, Vector2(sz.x * 0.5, top_y + 26.0), time_line, HORIZONTAL_ALIGNMENT_CENTER, -1, 18 if not compact else 14, Color(1, 0.9, 0.5))
	# checklist
	var cy := 64.0
	for item in checklist:
		var col: Color = Color(0.5, 1.0, 0.55) if item[1] else Color(1, 1, 1)
		var mark := "✓ " if item[1] else "○ "
		draw_string(font_b, Vector2(20.0, cy), mark + item[0], HORIZONTAL_ALIGNMENT_LEFT, 420.0, 15 if not compact else 12, col)
		cy += 20.0
	# nav arrow
	if nav_bearing >= 0.0:
		var c := Vector2(sz.x * 0.5, 100.0)
		var rel := deg_to_rad(nav_bearing - p.heading_deg())
		var dir := Vector2(sin(rel), -cos(rel))
		var pts := PackedVector2Array([c + dir * 22.0, c + dir.rotated(2.5) * 16.0, c + dir * -4.0, c + dir.rotated(-2.5) * 16.0])
		draw_colored_polygon(pts, Color(1.0, 0.8, 0.2, 0.95))
		var dtxt := "%s  %.1f km" % [nav_text, nav_dist / 1000.0] if nav_dist >= 1000.0 else "%s  %d m" % [nav_text, int(nav_dist)]
		draw_string(font_b, Vector2(c.x + 32.0, c.y + 6.0), dtxt, HORIZONTAL_ALIGNMENT_LEFT, -1, 16 if not compact else 13, Color(1, 0.9, 0.5))

func _dial(c: Vector2, r: float, label: String) -> void:
	draw_circle(c, r + 3.0, Color(0.2, 0.22, 0.26))
	draw_circle(c, r, Color(0.04, 0.05, 0.07))
	draw_string(font, Vector2(c.x - r, c.y + r * 0.55), label, HORIZONTAL_ALIGNMENT_CENTER, r * 2.0, 10, Color(0.75, 0.8, 0.9))

func _needle(c: Vector2, r: float, ang: float, col: Color, w: float = 3.0, back: float = 0.15) -> void:
	var d := Vector2(sin(ang), -cos(ang))
	draw_line(c - d * r * back, c + d * r * 0.86, col, w)
	draw_circle(c, w * 1.3, col)

func _ticks(c: Vector2, r: float, a0: float, a1: float, n: int, major_every: int, col: Color) -> void:
	for i in range(n + 1):
		var a: float = lerp(a0, a1, float(i) / float(n))
		var d := Vector2(sin(a), -cos(a))
		var ln := 0.14 if i % major_every == 0 else 0.07
		draw_line(c + d * r * (0.95 - ln), c + d * r * 0.95, col, 2.0 if i % major_every == 0 else 1.0)

func _asi(c: Vector2, r: float, kt: float) -> void:
	_dial(c, r, "KNOTS")
	var vmax: float = plane.spec.Vne * 1.15
	var a0 := deg_to_rad(-150.0)
	var a1 := deg_to_rad(150.0)
	# coloured arcs: white (flaps), green, yellow, red
	var s := plane.spec
	var f := func(v: float) -> float: return lerp(a0, a1, clamp(v / vmax, 0.0, 1.0))
	var stall_kt := _stall_kt(s.flaps[0])
	var stall_fl := _stall_kt(s.flaps[s.flaps.size() - 1])
	draw_arc(c, r * 0.8, f.call(stall_fl) - PI * 0.5, f.call(float(s.Vfe) if s.Vfe > 0 else stall_fl) - PI * 0.5, 24, Color(0.95, 0.95, 0.95), 5.0)
	draw_arc(c, r * 0.88, f.call(stall_kt) - PI * 0.5, f.call(float(s.cruise) * 1.15) - PI * 0.5, 24, Color(0.2, 0.8, 0.3), 5.0)
	draw_arc(c, r * 0.88, f.call(float(s.cruise) * 1.15) - PI * 0.5, f.call(float(s.Vne)) - PI * 0.5, 24, Color(0.95, 0.85, 0.2), 5.0)
	draw_arc(c, r * 0.88, f.call(float(s.Vne)) - PI * 0.5, a1 - PI * 0.5, 8, Color(0.95, 0.2, 0.2), 5.0)
	_ticks(c, r, a0, a1, 10, 2, Color(0.85, 0.85, 0.85))
	_needle(c, r, f.call(kt), Color(1, 1, 1))
	draw_string(font_b, Vector2(c.x - r, c.y - r * 0.3), "%d" % int(kt), HORIZONTAL_ALIGNMENT_CENTER, r * 2.0, 16, Color(1, 1, 1))

func _stall_kt(flap: float) -> float:
	var s := plane.spec
	var clm: float = s.CLmax + flap * s.flapCL
	var v: float = sqrt(2.0 * s.mass * 9.81 / (1.225 * s.S * clm))
	return v / Planes.KT

func _attitude(c: Vector2, r: float, pitch: float, bank: float) -> void:
	draw_circle(c, r + 3.0, Color(0.2, 0.22, 0.26))
	# clipped horizon: draw with a polygon approximation inside circle
	var b := deg_to_rad(bank)
	var off: float = clamp(pitch, -45.0, 45.0) / 45.0 * r * 0.9
	var up := Vector2(sin(b), -cos(b))
	var rt := Vector2(cos(b), sin(b))
	var hc: Vector2 = c - up * off
	var dn: float = (hc - c).dot(up)
	var half := sqrt(max(r * r - dn * dn, 0.0))
	var i1: Vector2 = c + up * dn + rt * half
	var i2: Vector2 = c + up * dn - rt * half
	draw_circle(c, r, Color(0.25, 0.5, 0.95))
	if abs(dn) < r:
		var ang1: float = (i1 - c).angle()
		var ang2: float = (i2 - c).angle()
		var span := wrapf(ang2 - ang1, 0.0, TAU)
		var start := ang1
		var mid := c + Vector2(cos(start + span * 0.5), sin(start + span * 0.5)) * r
		if (mid - hc).dot(up) > 0.0:
			start = ang2
			span = TAU - span
		var poly := PackedVector2Array()
		var nn := 24
		for k in range(nn + 1):
			var a: float = start + span * float(k) / float(nn)
			poly.append(c + Vector2(cos(a), sin(a)) * r)
		draw_colored_polygon(poly, Color(0.55, 0.35, 0.15))
	elif dn >= r:
		draw_circle(c, r, Color(0.55, 0.35, 0.15))
	# pitch ladder
	for d in [-20, -10, 10, 20]:
		var y: float = (float(d) - clamp(pitch, -45.0, 45.0)) / 45.0 * r * 0.9
		if abs(y) < r * 0.75:
			var w := r * (0.3 if d % 20 == 0 else 0.18)
			var p0: Vector2 = c + up * y - rt * w
			var p1 := c + up * y + rt * w
			draw_line(p0, p1, Color(1, 1, 1, 0.8), 1.5)
	# horizon line
	if abs(dn) < r:
		draw_line(i1, i2, Color(1, 1, 1), 2.0)
	# fixed aircraft symbol
	draw_line(c + Vector2(-r * 0.5, 0), c + Vector2(-r * 0.15, 0), Color(1, 0.8, 0.1), 3.0)
	draw_line(c + Vector2(r * 0.15, 0), c + Vector2(r * 0.5, 0), Color(1, 0.8, 0.1), 3.0)
	draw_circle(c, 3.0, Color(1, 0.8, 0.1))
	# bank marks
	for d in [-60, -30, -10, 0, 10, 30, 60]:
		var a := deg_to_rad(float(d))
		var dv := Vector2(sin(a), -cos(a))
		draw_line(c + dv * r * 0.86, c + dv * r * (0.98 if d % 30 == 0 else 0.93), Color(1, 1, 1), 2.0)
	var bp := c + Vector2(sin(-b), -cos(-b)) * r * 0.78
	draw_colored_polygon(PackedVector2Array([bp + Vector2(0, -6).rotated(-b), bp + Vector2(-5, 4).rotated(-b), bp + Vector2(5, 4).rotated(-b)]), Color(1, 0.8, 0.1))
	draw_string(font, Vector2(c.x - r, c.y + r * 0.75), "ATTITUDE", HORIZONTAL_ALIGNMENT_CENTER, r * 2.0, 9, Color(1, 1, 1, 0.8))

func _altimeter(c: Vector2, r: float, ft: float) -> void:
	_dial(c, r, "FEET")
	_ticks(c, r, 0.0, TAU, 50, 5, Color(0.85, 0.85, 0.85))
	for i in range(10):
		var a := TAU * float(i) / 10.0
		var d := Vector2(sin(a), -cos(a))
		draw_string(font, Vector2(c.x + d.x * r * 0.66 - 6.0, c.y + d.y * r * 0.66 + 4.0), "%d" % i, HORIZONTAL_ALIGNMENT_LEFT, -1, 10, Color(0.9, 0.9, 0.9))
	var f: float = max(ft, 0.0)
	_needle(c, r * 0.62, TAU * fmod(f / 10000.0, 1.0), Color(1, 1, 1), 4.0, 0.1)
	_needle(c, r * 0.9, TAU * fmod(f / 1000.0, 1.0), Color(1, 1, 1), 2.5, 0.1)
	draw_string(font_b, Vector2(c.x - r, c.y + r * 0.42), "%d" % int(f), HORIZONTAL_ALIGNMENT_CENTER, r * 2.0, 12, Color(0.6, 1.0, 0.6))

func _vsi(c: Vector2, r: float, fpm: float) -> void:
	_dial(c, r, "FT/MIN x100")
	var a0 := deg_to_rad(-170.0)
	var a1 := deg_to_rad(170.0)
	_ticks(c, r, -deg_to_rad(90.0), deg_to_rad(90.0), 8, 2, Color(0.85, 0.85, 0.85))
	for i in [-20, -10, 0, 10, 20]:
		var a := -PI * 0.5 + float(i) / 20.0 * deg_to_rad(170.0)
		var d := Vector2(sin(a), -cos(a))
		draw_string(font, Vector2(c.x + d.x * r * 0.7 - 6.0, c.y + d.y * r * 0.7 + 4.0), "%d" % abs(i), HORIZONTAL_ALIGNMENT_LEFT, -1, 10, Color(0.9, 0.9, 0.9))
	var v: float = clamp(fpm / 2000.0, -1.0, 1.0)
	_needle(c, r, -PI * 0.5 + v * deg_to_rad(170.0), Color(1, 1, 1))
	draw_string(font_b, Vector2(c.x - r, c.y + r * 0.35), "%+d" % int(fpm), HORIZONTAL_ALIGNMENT_CENTER, r * 2.0, 12, Color(0.9, 0.9, 1.0))

func _heading(c: Vector2, r: float, hdg: float) -> void:
	_dial(c, r, "")
	var names := ["N", "3", "6", "E", "12", "15", "S", "21", "24", "W", "30", "33"]
	for i in range(36):
		var a := deg_to_rad(float(i) * 10.0 - hdg)
		var d := Vector2(sin(a), -cos(a))
		draw_line(c + d * r * (0.82 if i % 3 == 0 else 0.88), c + d * r * 0.95, Color(0.85, 0.85, 0.85), 2.0 if i % 3 == 0 else 1.0)
		if i % 3 == 0:
			var nm: String = names[i / 3]
			var col := Color(1, 0.8, 0.2) if nm in ["N", "E", "S", "W"] else Color(0.9, 0.9, 0.9)
			draw_string(font, Vector2(c.x + d.x * r * 0.66 - 7.0, c.y + d.y * r * 0.66 + 4.0), nm, HORIZONTAL_ALIGNMENT_LEFT, -1, 10, col)
	# plane symbol
	draw_line(c + Vector2(0, -r * 0.5), c + Vector2(0, r * 0.25), Color(1, 0.8, 0.1), 3.0)
	draw_line(c + Vector2(-r * 0.3, -r * 0.05), c + Vector2(r * 0.3, -r * 0.05), Color(1, 0.8, 0.1), 3.0)
	draw_colored_polygon(PackedVector2Array([c + Vector2(0, -r * 0.98), c + Vector2(-6, -r * 0.84), c + Vector2(6, -r * 0.84)]), Color(1, 0.8, 0.1))
	draw_string(font_b, Vector2(c.x - r, c.y + r * 0.7), "%03d°" % int(round(hdg)) if int(round(hdg)) < 360 else "000°", HORIZONTAL_ALIGNMENT_CENTER, r * 2.0, 12, Color(1, 1, 1))
	if nav_bearing >= 0.0:
		var a := deg_to_rad(nav_bearing - hdg)
		var d := Vector2(sin(a), -cos(a))
		draw_colored_polygon(PackedVector2Array([c + d * r * 0.78, c + d.rotated(2.6) * r * 0.12, c + d.rotated(-2.6) * r * 0.12]), Color(0.9, 0.3, 1.0, 0.9))

func _engine(c: Vector2, r: float) -> void:
	var s := plane.spec
	var is_prop: bool = s.kind == "prop"
	_dial(c, r, "RPM" if is_prop else "N1 %")
	var a0 := deg_to_rad(-135.0)
	var a1 := deg_to_rad(135.0)
	_ticks(c, r, a0, a1, 10, 2, Color(0.85, 0.85, 0.85))
	var vmax: float = float(s.max_rpm) * 1.1 if is_prop else 110.0
	var v: float = plane.rpm / vmax
	draw_arc(c, r * 0.88, lerp(a0, a1, (float(s.max_rpm) * 0.85 if is_prop else 95.0) / vmax) - PI * 0.5, a1 - PI * 0.5, 8, Color(0.95, 0.2, 0.2), 5.0)
	_needle(c, r, lerp(a0, a1, clamp(v, 0.0, 1.0)), Color(1, 1, 1))
	var lbl := "%d" % int(plane.rpm) if is_prop else "%d%%" % int(plane.rpm)
	draw_string(font_b, Vector2(c.x - r, c.y + r * 0.4), lbl, HORIZONTAL_ALIGNMENT_CENTER, r * 2.0, 12, Color(1, 1, 1))
	# throttle bar on the side
	var bx := c.x + r + 4.0
	draw_rect(Rect2(bx, c.y - r, 6.0, r * 2.0), Color(0.15, 0.15, 0.18))
	draw_rect(Rect2(bx, c.y + r - r * 2.0 * plane.throttle, 6.0, r * 2.0 * plane.throttle), Color(1.0, 0.6, 0.15) if not plane.ab else Color(1.0, 0.3, 0.1))

files.shaders/water.gdshader:
shader_type spatial;
render_mode cull_disabled, depth_draw_opaque;
uniform float t = 0.0;

void vertex() {
	float w = sin(VERTEX.x * 0.02 + t * 1.2) * 0.3 + sin(VERTEX.z * 0.017 - t * 0.9) * 0.3;
	VERTEX.y += w;
}

void fragment() {
	vec2 p = (NODE_POSITION_WORLD.xz * 0.0 + (INV_VIEW_MATRIX * vec4(VERTEX, 1.0)).xz);
	float n1 = sin(p.x * 0.09 + t * 1.3) + sin(p.y * 0.07 - t * 1.1) + sin((p.x + p.y) * 0.05 + t * 0.7);
	float n2 = sin(p.x * 0.31 - t * 2.0) + sin(p.y * 0.27 + t * 1.7);
	vec3 n = normalize(vec3(n1 * 0.08 + n2 * 0.03, 1.0, n1 * 0.06 - n2 * 0.03));
	NORMAL = normalize((VIEW_MATRIX * vec4(n, 0.0)).xyz);
	vec3 deep = vec3(0.03, 0.22, 0.42);
	vec3 shallow = vec3(0.12, 0.55, 0.65);
	float f = pow(1.0 - clamp(dot(NORMAL, VIEW), 0.0, 1.0), 3.0);
	ALBEDO = mix(deep, shallow, 0.4 + 0.3 * sin(n1)) ;
	ALPHA = 0.9;
	ROUGHNESS = 0.08;
	METALLIC = 0.2;
	SPECULAR = 0.6 + f * 0.4;
}
